static __attribute__((noreturn)) THD_FUNCTION(Thread2, arg)
{
    (void)arg;
    chRegSetThreadName("button");
    while (1)
    {
      disp_process();
      ui_process();
      chThdSleepMilliseconds(10);
      stat.fps_count++;

      {
        int flag = tlv320aic3204_get_sticky_flag_register();
        if (flag & AIC3204_STICKY_ADC_OVERFLOW)
          stat.overflow_count++;
      }
    }
